INSERT INTO knowledge.abilities (id,kind,name,variant_id,source_id,provenance,confidence,review_status,exact_visible_text) VALUES ('ned-hand-king-called-trait','trait','The King Called On Me To Serve','screenshot-variant-ned-stark-hand-of-the-king-red',103882,'Screenshot Verified',1,'complete','Leader · Once. At the start of combat, Ned grants up to 2 random allies LOYALTY, 1 BLOCK and +8% Stamina and spawns 1 Justice Gem. When a Justice Gem hits a BRITTLE enemy, Ned strikes them for 75% ATK Physical Damage. 5-star locked upgrade shown: +7% Stamina and +1 Justice Gems.') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge.ability_effects (id,ability_id,effect_kind,exact_visible_text) VALUES ('ned-hand-king-called-trait-effect','ned-hand-king-called-trait','source_verified_wording','Leader · Once. At the start of combat, Ned grants up to 2 random allies LOYALTY, 1 BLOCK and +8% Stamina and spawns 1 Justice Gem. When a Justice Gem hits a BRITTLE enemy, Ned strikes them for 75% ATK Physical Damage. 5-star locked upgrade shown: +7% Stamina and +1 Justice Gems.') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge.abilities (id,kind,name,variant_id,source_id,provenance,confidence,review_status,exact_visible_text) VALUES ('ned-hand-life-precious-trait','trait','You Think My Life Is Precious To Me? II','screenshot-variant-ned-stark-hand-of-the-king-red',103886,'Screenshot Verified',1,'complete','Per Turn. Whenever an enemy is afflicted with ICE, up to 3 times a turn, Ned HEALS himself for 8% of his ATK. If that ICE was applied by an ally with LOYALTY, that ally is also HEALED. 6-star locked upgrade shown: HEALING increased by 2% ATK, and can trigger 1 additional time per turn. Stats Bonus: +5% HP and +10% DEF. 5-star locked: +5% ATK. 7-star locked: +5% DEF.') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge.ability_effects (id,ability_id,effect_kind,exact_visible_text) VALUES ('ned-hand-life-precious-trait-effect','ned-hand-life-precious-trait','source_verified_wording','Per Turn. Whenever an enemy is afflicted with ICE, up to 3 times a turn, Ned HEALS himself for 8% of his ATK. If that ICE was applied by an ally with LOYALTY, that ally is also HEALED. 6-star locked upgrade shown: HEALING increased by 2% ATK, and can trigger 1 additional time per turn. Stats Bonus: +5% HP and +10% DEF. 5-star locked: +5% ATK. 7-star locked: +5% DEF.') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge.abilities (id,kind,name,variant_id,source_id,provenance,confidence,review_status,exact_visible_text) VALUES ('ned-hand-blood-on-my-hands-skill','champion_skill','I Will Not Have Their Blood On My Hands','screenshot-variant-ned-stark-hand-of-the-king-red',103887,'Screenshot Verified',1,'complete','Skill Level 5 · Normal Stamina Speed · ADD BUFF · SPAWN GEM. Ned grants a target ally LOYALTY, with a 45% chance to also grant BLOCK. He then spawns 1 Justice Gem. If Ned is targeted, he spawns 1 additional Justice Gem. Level 6 upgrade shown: +5% chance to give BLOCK.') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge.ability_effects (id,ability_id,effect_kind,exact_visible_text) VALUES ('ned-hand-blood-on-my-hands-skill-effect','ned-hand-blood-on-my-hands-skill','source_verified_wording','Skill Level 5 · Normal Stamina Speed · ADD BUFF · SPAWN GEM. Ned grants a target ally LOYALTY, with a 45% chance to also grant BLOCK. He then spawns 1 Justice Gem. If Ned is targeted, he spawns 1 additional Justice Gem. Level 6 upgrade shown: +5% chance to give BLOCK.') ON CONFLICT (id) DO NOTHING;
INSERT INTO knowledge.status_definitions (status_id,status_name,exact_visible_definition,completion_state,source_id) VALUES (103888,'LOYALTY','If POISON, DECEIVE, or SCOUT is inflicted on this Champion, Ned gains the debuff instead for 3 turns. Ned has a 50% chance to cleanse it from himself immediately.','complete',103888) ON CONFLICT (status_id) DO NOTHING;
